{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/cta-actions.json
    The actions of a call to action: one or two links (ActionGroup), or an email field with a button (actions form).
    Props (p): id, actions, center. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_actions = (p.actions ?? null) -%}
{%- set v_center = (p.center ?? false) -%}
{%- if og_t(og_eq(og_get(v_actions, ['mode']), 'form')) %}
  {%- set c_4 -%}
    {%- set c_1 -%}
      {{ og_text(og_get(v_actions, ['emailLabel'])) }}
    {%- endset -%}
    {{ include('compose/Label.html.twig', {'htmlFor': og_s(og_tpl('{0}-email', [v_id])), 'class': 'sr-only', 'children': c_1}, with_context = false) }}
    {%- set c_3 -%}
      {{ include('compose/Input.html.twig', {'type': 'email', 'name': 'email', 'class': 'min-w-0 flex-1', 'attrs': og_attrs(['id', og_tpl('{0}-email', [v_id]), 'data-testid', 'field'])}, with_context = false) }}
      {%- set c_2 -%}
        {{ og_text(og_get(v_actions, ['cta'])) }}
      {%- endset -%}
      {{ include('compose/Button.html.twig', {'variant': 'default', 'size': 'default', 'type': 'submit', 'attrs': og_attrs(['data-testid', 'submit']), 'children': c_2}, with_context = false) }}
    {%- endset -%}
    {{ include('compose/Group.html.twig', {'gap': '2', 'align': 'start', 'class': 'w-full flex-wrap', 'children': c_3}, with_context = false) }}
  {%- endset -%}
  {{ include('compose/Form.html.twig', {'method': 'dialog', 'class': og_s(og_cnv(['w-full max-w-md', (og_t(v_center) ? 'mx-auto' : '')])), 'attrs': og_attrs(['data-testid', 'email-form']), 'children': c_4}, with_context = false) }}
{%- else %}
  {{ include('blocks/action-group.html.twig', {'p': {'primary': og_get(v_actions, ['cta']), 'primaryHref': og_get(v_actions, ['href']), 'secondary': (og_t(og_eq(og_get(v_actions, ['mode']), 'two')) ? og_get(v_actions, ['secondary']) : null), 'secondaryHref': og_get(v_actions, ['secondaryHref']), 'align': (og_t(v_center) ? 'center' : 'start')}}, with_context = false) }}
{%- endif %}
